     1	//! `measureText` (road map 10 §5c): lay one `<text>` out with the shared
     2	//! options and read the text node's own box and its glyphs' ink box.
     3	
     4	use std::sync::Mutex;
     5	
     6	use resvg::usvg;
     7	
     8	use crate::diagnostic::Diagnostic;
     9	use crate::library::{Library, MemoKey, Probe};
    10	use crate::raster::escape_xml;
    11	
    12	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    13	pub enum FontStyle {
    14	    Normal,
    15	    Italic,
    16	    Oblique,
    17	}
    18	
    19	impl FontStyle {
    20	    fn as_css(self) -> &'static str {
    21	        match self {
    22	            FontStyle::Normal => "normal",
    23	            FontStyle::Italic => "italic",
    24	            FontStyle::Oblique => "oblique",
    25	        }
    26	    }
    27	}
    28	
    29	/// The font a text is measured in.
    30	#[derive(Debug, Clone, PartialEq)]
    31	pub struct TextFont {
    32	    pub family: String,
    33	    pub size: f64,
    34	    pub weight: u16,
    35	    pub style: FontStyle,
    36	    pub letter_spacing: f64,
    37	    /// `xml:space="preserve"` on the probe `<text>` (G-22): runs of spaces
    38	    /// beside a drawn glyph count instead of collapsing.
    39	    pub preserve_space: bool,
    40	}
    41	
    42	/// A text's advance, its box about the baseline, and its ink.
    43	#[derive(Debug, Clone, Copy, PartialEq)]
    44	pub struct TextMetrics {
    45	    pub width: f64,
    46	    pub ascent: f64,
    47	    pub descent: f64,
    48	    pub line_height: f64,
    49	    pub ink_x: f64,
    50	    pub ink_width: f64,
    51	}
    52	
    53	impl TextMetrics {
    54	    const ZERO: TextMetrics = TextMetrics {
    55	        width: 0.0,
    56	        ascent: 0.0,
    57	        descent: 0.0,
    58	        line_height: 0.0,
    59	        ink_x: 0.0,
    60	        ink_width: 0.0,
    61	    };
    62	
    63	    /// Keys `width, ascent, descent, lineHeight, inkX, inkWidth`, in order.
    64	    pub fn to_json(&self) -> serde_json::Value {
    65	        serde_json::json!({
    66	            "width": self.width,
    67	            "ascent": self.ascent,
    68	            "descent": self.descent,
    69	            "lineHeight": self.line_height,
    70	            "inkX": self.ink_x,
    71	            "inkWidth": self.ink_width,
    72	        })
    73	    }
    74	}
    75	
    76	/// Measures `text` in `font`, memoised in the library. Whitespace-only text
    77	/// measures zero under either `preserve_space` (G-22: usvg lays out no text
    78	/// node for a text with no outlines, preserved or not); a family with no
    79	/// face in the set is an error naming it.
    80	pub fn measure_text(
    81	    library: &Library,
    82	    text: &str,
    83	    font: &TextFont,
    84	) -> Result<TextMetrics, Diagnostic> {
    85	    if !font.size.is_finite() || font.size <= 0.0 {
    86	        return Err(Diagnostic::error(format!(
    87	            "measureText: size {} must be finite and > 0",
    88	            font.size
    89	        )));
    90	    }
    91	    if font.weight == 0 || font.weight > 1000 {
    92	        return Err(Diagnostic::error(format!(
    93	            "measureText: weight {} must be 1–1000",
    94	            font.weight
    95	        )));
    96	    }
    97	    if !font.letter_spacing.is_finite() {
    98	        return Err(Diagnostic::error(
    99	            "measureText: letterSpacing must be finite",
   100	        ));
   101	    }
   102	    if text.trim().is_empty() {
   103	        return Ok(TextMetrics::ZERO);
   104	    }
   105	    let key: MemoKey = (
   106	        font.family.clone(),
   107	        font.size.to_bits(),
   108	        font.weight,
   109	        font.style,
   110	        font.letter_spacing.to_bits(),
   111	        font.preserve_space,
   112	        text.to_string(),
   113	    );
   114	    if let Some(metrics) = library.memo_get(&key) {
   115	        return Ok(metrics);
   116	    }
   117	    let metrics = measure_uncached(library, text, font)?;
   118	    library.memo_put(key, metrics);
   119	    Ok(metrics)
   120	}
   121	
   122	fn measure_uncached(
   123	    library: &Library,
   124	    text: &str,
   125	    font: &TextFont,
   126	) -> Result<TextMetrics, Diagnostic> {
   127	    let size = font.size;
   128	    let baseline = size * 2.0;
   129	    let svg = format!(
   130	        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{w}\" height=\"{h}\">\
   131	         <text x=\"0\" y=\"{baseline}\" font-family=\"{family}\" font-size=\"{size}\" \
   132	         font-weight=\"{weight}\" font-style=\"{style}\" letter-spacing=\"{spacing}\"{space}>{t}</text></svg>",
   133	        w = (size * 64.0).ceil(),
   134	        h = (size * 4.0).ceil(),
   135	        family = escape_xml(&family_value(&font.family)),
   136	        weight = font.weight,
   137	        style = font.style.as_css(),
   138	        spacing = font.letter_spacing,
   139	        space = if font.preserve_space {
   140	            " xml:space=\"preserve\""
   141	        } else {
   142	            ""
   143	        },
   144	        t = escape_xml(text),
   145	    );
   146	    let probe = Mutex::new(Probe::default());
   147	    let options = library.options(&probe);
   148	    let tree = usvg::Tree::from_str(&svg, &options)
   149	        .map_err(|e| Diagnostic::error(format!("measureText: {e}")))?;
   150	    let node = find_text(tree.root()).ok_or_else(|| {
   151	        Diagnostic::error(format!(
   152	            "measureText: no face for family \"{}\"; the set has: {}",
   153	            font.family,
   154	            library.families().join(", ")
   155	        ))
   156	    })?;
   157	    let bbox = node.bounding_box();
   158	    let ink = node.flattened().abs_bounding_box();
   159	    let ascent = baseline - bbox.top() as f64;
   160	    let descent = bbox.bottom() as f64 - baseline;
   161	    Ok(TextMetrics {
   162	        width: bbox.width() as f64,
   163	        ascent,
   164	        descent,
   165	        line_height: ascent + descent,
   166	        ink_x: ink.x() as f64,
   167	        ink_width: ink.width() as f64,
   168	    })
   169	}
   170	
   171	/// The CSS generic keywords as svgtypes reads them, case-sensitive as usvg
   172	/// matches them (G-6).
   173	const GENERIC_FAMILIES: [&str; 5] = ["serif", "sans-serif", "cursive", "fantasy", "monospace"];
   174	
   175	/// A generic keyword is written bare, so it is the keyword (G-6); any other
   176	/// family is quoted, so a digit-led word (`Source Sans 3`) parses — as
   177	/// `stdlib.js`'s `textLines` writes it.
   178	fn family_value(family: &str) -> String {
   179	    if GENERIC_FAMILIES.contains(&family) {
   180	        family.to_string()
   181	    } else {
   182	        format!("'{}'", family.replace('\'', ""))
   183	    }
   184	}
   185	
   186	fn find_text(group: &usvg::Group) -> Option<&usvg::Text> {
   187	    for node in group.children() {
   188	        match node {
   189	            usvg::Node::Text(text) => return Some(text),
   190	            usvg::Node::Group(inner) => {
   191	                if let Some(found) = find_text(inner) {
   192	                    return Some(found);
   193	                }
   194	            }
   195	            _ => {}
   196	        }
   197	    }
   198	    None
   199	}
     1	//! G-5's sandbox (road map 10 §5b): the script evaluated after the standard
     2	//! library that freezes the clock and removes randomness and every second
     3	//! source of code, and the module loader that resolves no specifier.
     4	
     5	use rquickjs::loader::{ImportAttributes, Loader, Resolver};
     6	use rquickjs::module::Declared;
     7	use rquickjs::Module;
     8	
     9	/// The sentence an `import` of any specifier is refused with; QuickJS
    10	/// prefixes it with `Error resolving module '<x>' from '<name>': `.
    11	pub(crate) const IMPORT_REFUSAL: &str =
    12	    "imports are not available in a graphic; the standard library is global";
    13	
    14	/// Evaluated as a script, last: `Date` frozen at 2000-01-01T00:00:00Z (its
    15	/// prototype's `constructor` too), `Math.random` throwing, `eval`,
    16	/// `Function` and the three other function-kind constructors gone,
    17	/// `WebAssembly` and `performance` (`JS_NewContext` installs a clock there)
    18	/// deleted.
    19	pub(crate) const SANDBOX: &str = r#"
    20	(() => {
    21	  const RealDate = Date;
    22	  const EPOCH = 946684800000;
    23	  function FrozenDate(...args) {
    24	    if (!new.target) return new RealDate(EPOCH).toString();
    25	    return args.length ? new RealDate(...args) : new RealDate(EPOCH);
    26	  }
    27	  FrozenDate.now = () => EPOCH;
    28	  FrozenDate.UTC = RealDate.UTC;
    29	  FrozenDate.parse = RealDate.parse;
    30	  FrozenDate.prototype = RealDate.prototype;
    31	  Object.defineProperty(RealDate.prototype, "constructor", { value: FrozenDate });
    32	  globalThis.Date = FrozenDate;
    33	  Math.random = function () { throw new Error("Math.random is not available; use random(seed)"); };
    34	  const refuse = function () { throw new Error("Function is not available in a graphic; the module is the one source of code"); };
    35	  Object.defineProperty(Function.prototype, "constructor", { value: refuse });
    36	  for (const f of [async function () {}, function* () {}, async function* () {}]) {
    37	    Object.defineProperty(Object.getPrototypeOf(f), "constructor", { value: refuse });
    38	  }
    39	  delete globalThis.eval;
    40	  globalThis.Function = refuse;
    41	  delete globalThis.WebAssembly;
    42	  delete globalThis.performance;
    43	})();
    44	"#;
    45	
    46	/// The resolver and loader of every engine: both refuse.
    47	pub(crate) struct NoImports;
    48	
    49	impl Resolver for NoImports {
    50	    fn resolve<'js>(
    51	        &mut self,
    52	        _ctx: &rquickjs::Ctx<'js>,
    53	        base: &str,
    54	        name: &str,
    55	        _attributes: Option<ImportAttributes<'js>>,
    56	    ) -> rquickjs::Result<String> {
    57	        Err(rquickjs::Error::new_resolving_message(
    58	            base,
    59	            name,
    60	            IMPORT_REFUSAL,
    61	        ))
    62	    }
    63	}
    64	
    65	impl Loader for NoImports {
    66	    fn load<'js>(
    67	        &mut self,
    68	        _ctx: &rquickjs::Ctx<'js>,
    69	        name: &str,
    70	        _attributes: Option<ImportAttributes<'js>>,
    71	    ) -> rquickjs::Result<Module<'js, Declared>> {
    72	        Err(rquickjs::Error::new_loading_message(name, IMPORT_REFUSAL))
    73	    }
    74	}
     1	//! A module's schema and the props drawn with it (road map 10 §5c, G-4):
     2	//! the schema is checked strictly when a module compiles; stored props are
     3	//! laid over it leniently at render time, every surprise a warning.
     4	
     5	use serde_json::{Map, Value};
     6	
     7	use crate::diagnostic::Diagnostic;
     8	
     9	/// The most keys a module's schema may declare (G-4). The core restates it
    10	/// as `GRAPHIC_MAX_PROPS`, since G-2 forbids importing it there;
    11	/// `core/tests/graphic_ffi.rs`'s `one_max_props_in_the_engine_and_the_core`
    12	/// pins the two, and `tests/reference.rs` pins the number the reference states.
    13	pub const MAX_PROPS: usize = 64;
    14	/// The most options an `enum` entry may list (G-4). The core restates it as
    15	/// `GRAPHIC_MAX_OPTIONS`, pinned in `core/tests/graphic_ffi.rs`.
    16	pub const MAX_OPTIONS: usize = 32;
    17	/// The most characters a `string` entry's default may hold (G-4). The core
    18	/// restates it as `GRAPHIC_MAX_STRING`, pinned in `core/tests/graphic_ffi.rs`.
    19	pub const MAX_STRING: usize = 4096;
    20	/// A schema entry's six types, in the order the refusal lists them (G-4). The
    21	/// core restates it as `GRAPHIC_TYPES`, pinned in `core/tests/graphic_ffi.rs`.
    22	pub const TYPES: [&str; 6] = ["string", "number", "boolean", "color", "enum", "asset"];
    23	
    24	/// §5c's rules for a schema, each refused in its own sentence. `colour`
    25	/// answers whether G-12 takes a `color` entry's default (spec §11 G-25).
    26	pub(crate) fn check_schema(
    27	    schema: &Value,
    28	    colour: &dyn Fn(&str) -> bool,
    29	) -> Result<(), Diagnostic> {
    30	    let Some(entries) = schema.as_object() else {
    31	        return Err(Diagnostic::error("schema must be an object"));
    32	    };
    33	    if entries.len() > MAX_PROPS {
    34	        return Err(Diagnostic::error(format!(
    35	            "schema has {} keys; the most is {MAX_PROPS}",
    36	            entries.len()
    37	        )));
    38	    }
    39	    for (key, entry) in entries {
    40	        check_entry(key, entry, colour).map_err(Diagnostic::error)?;
    41	    }
    42	    Ok(())
    43	}
    44	
    45	/// Each string `default` of a `type: "color"` entry, in schema order — what
    46	/// `check_schema`'s `colour` is asked about. Checks nothing else.
    47	pub(crate) fn colour_defaults(schema: &Value) -> Vec<String> {
    48	    let Some(entries) = schema.as_object() else {
    49	        return Vec::new();
    50	    };
    51	    entries
    52	        .values()
    53	        .filter(|entry| entry.get("type").and_then(Value::as_str) == Some("color"))
    54	        .filter_map(|entry| entry.get("default").and_then(Value::as_str))
    55	        .map(str::to_string)
    56	        .collect()
    57	}
    58	
    59	fn check_entry(key: &str, entry: &Value, colour: &dyn Fn(&str) -> bool) -> Result<(), String> {
    60	    if !is_name(key) {
    61	        return Err(format!(
    62	            "schema key \"{key}\" is not a name (letters, digits and _, starting with a letter or _, at most 32 characters)"
    63	        ));
    64	    }
    65	    let Some(kind) = entry.get("type").and_then(Value::as_str) else {
    66	        return Err(format!("schema.{key} must be an object with a type"));
    67	    };
    68	    if !TYPES.contains(&kind) {
    69	        return Err(format!(
    70	            "schema.{key}.type \"{kind}\" is not one of string, number, boolean, color, enum, asset"
    71	        ));
    72	    }
    73	    if kind == "enum" {
    74	        let good = entry
    75	            .get("options")
    76	            .and_then(Value::as_array)
    77	            .is_some_and(|o| {
    78	                (1..=MAX_OPTIONS).contains(&o.len()) && o.iter().all(Value::is_string)
    79	            });
    80	        if !good {
    81	            return Err(format!("schema.{key}.options must be 1–32 strings"));
    82	        }
    83	    }
    84	    let Some(default) = entry.get("default") else {
    85	        return Err(format!("schema.{key} has no default"));
    86	    };
    87	    let fits = match kind {
    88	        "string" => default
    89	            .as_str()
    90	            .is_some_and(|s| s.chars().count() <= MAX_STRING),
    91	        "color" => default.as_str().is_some_and(colour),
    92	        _ => fits(kind, entry, default),
    93	    };
    94	    if !fits {
    95	        return Err(format!("schema.{key}.default {default} is not a {kind}"));
    96	    }
    97	    if let Some(animate) = entry.get("animate").filter(|a| !a.is_boolean()) {
    98	        return Err(format!("schema.{key}.animate {animate} is not a boolean"));
    99	    }
   100	    Ok(())
   101	}
   102	
   103	fn is_name(key: &str) -> bool {
   104	    let mut chars = key.chars();
   105	    let head = chars
   106	        .next()
   107	        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_');
   108	    head && key.len() <= 32 && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
   109	}
   110	
   111	/// Whether `value` is of the entry's `kind` (render time: a string's length
   112	/// is not checked).
   113	fn fits(kind: &str, entry: &Value, value: &Value) -> bool {
   114	    match kind {
   115	        "string" | "color" => value.is_string(),
   116	        "number" => value.as_f64().is_some_and(f64::is_finite),
   117	        "boolean" => value.is_boolean(),
   118	        "enum" => options(entry).contains(value),
   119	        "asset" => value.is_string() || value.is_null(),
   120	        _ => false,
   121	    }
   122	}
   123	
   124	fn options(entry: &Value) -> Vec<Value> {
   125	    entry
   126	        .get("options")
   127	        .and_then(Value::as_array)
   128	        .cloned()
   129	        .unwrap_or_default()
   130	}
   131	
   132	/// `stored` laid over the schema's defaults, in the schema's key order,
   133	/// then the stored keys the schema lacks, passed through. Never refuses:
   134	/// every key that did not fit is the default plus a warning. An `asset`
   135	/// stored as `""` is "no image" and is handed to `render` as `null`, with
   136	/// no warning (spec §11 G-42).
   137	pub fn overlay(schema: &Value, stored: &Value) -> (Value, Vec<Diagnostic>) {
   138	    let mut warnings = Vec::new();
   139	    let empty = Map::new();
   140	    let stored = match stored {
   141	        Value::Object(map) => map,
   142	        other => {
   143	            warnings.push(Diagnostic::warning(format!(
   144	                "props is {}, not an object; the defaults are used",
   145	                kind_of(other)
   146	            )));
   147	            &empty
   148	        }
   149	    };
   150	    let entries = schema.as_object().cloned().unwrap_or_default();
   151	    let mut props = Map::new();
   152	    for (key, entry) in &entries {
   153	        let default = entry.get("default").cloned().unwrap_or(Value::Null);
   154	        let kind = entry.get("type").and_then(Value::as_str).unwrap_or("");
   155	        let value = match stored.get(key) {
   156	            None => default,
   157	            // "No image" (G-42): an asset stored as `""` reaches `render` as `null`.
   158	            Some(Value::String(text)) if kind == "asset" && text.is_empty() => Value::Null,
   159	            Some(value) if fits(kind, entry, value) => value.clone(),
   160	            Some(value) if kind == "enum" && value.is_string() => {
   161	                warnings.push(Diagnostic::warning(format!(
   162	                    "props.{key} = {value} is not one of {}; the default {default} is used",
   163	                    Value::from(options(entry))
   164	                )));
   165	                default
   166	            }
   167	            Some(value) => {
   168	                warnings.push(Diagnostic::warning(format!(
   169	                    "props.{key} is {} but the schema says {kind}; the default {default} is used",
   170	                    kind_of(value)
   171	                )));
   172	                default
   173	            }
   174	        };
   175	        props.insert(key.clone(), value);
   176	    }
   177	    for (key, value) in stored {
   178	        if !entries.contains_key(key) {
   179	            warnings.push(Diagnostic::warning(format!(
   180	                "props.{key} is not in the schema; it is passed through"
   181	            )));
   182	            props.insert(key.clone(), value.clone());
   183	        }
   184	    }
   185	    (Value::Object(props), warnings)
   186	}
   187	
   188	fn kind_of(value: &Value) -> &'static str {
   189	    match value {
   190	        Value::String(_) => "a string",
   191	        Value::Number(_) => "a number",
   192	        Value::Bool(_) => "a boolean",
   193	        Value::Null => "null",
   194	        Value::Array(_) => "an array",
   195	        Value::Object(_) => "an object",
   196	    }
   197	}
     1	//! The host functions the standard library is built on (road map 10 §5c),
     2	//! installed as globals before `stdlib.js` runs: `__measureText`,
     3	//! `__assetNames`, `__warn` and `__namedColour`. What crosses back to
     4	//! JavaScript is JSON text; `stdlib.js` parses it.
     5	
     6	use std::cell::RefCell;
     7	use std::rc::Rc;
     8	use std::sync::Arc;
     9	
    10	use rquickjs::Function;
    11	
    12	use crate::diagnostic::Diagnostic;
    13	use crate::library::Library;
    14	use crate::measure::{measure_text, FontStyle, TextFont};
    15	
    16	/// Installs the four globals on `ctx`. `sink` collects `__warn`'s
    17	/// messages for the engine that owns it.
    18	pub(crate) fn install(
    19	    ctx: &rquickjs::Ctx<'_>,
    20	    library: &Arc<Library>,
    21	    sink: Rc<RefCell<Vec<String>>>,
    22	) -> Result<(), Diagnostic> {
    23	    let fonts = library.clone();
    24	    // No lock is held here around `measure_text`: its memo lock lives in
    25	    // `library.rs` and is taken only for the memo's own read and write.
    26	    let measure = Function::new(
    27	        ctx.clone(),
    28	        move |text: String,
    29	              family: String,
    30	              size: f64,
    31	              weight: f64,
    32	              style: String,
    33	              letter_spacing: f64,
    34	              xml_space: String| {
    35	            // Seven parameters: rquickjs 0.14's `FromParams` maximum.
    36	            let preserve_space = match xml_space.as_str() {
    37	                "default" => false,
    38	                "preserve" => true,
    39	                other => {
    40	                    let message = format!(
    41	                        "measureText: xmlSpace must be \"default\" or \"preserve\", not \"{other}\""
    42	                    );
    43	                    return serde_json::json!({ "error": message }).to_string();
    44	                }
    45	            };
    46	            let font = TextFont {
    47	                family,
    48	                size,
    49	                weight: weight as u16,
    50	                style: match style.as_str() {
    51	                    "italic" => FontStyle::Italic,
    52	                    "oblique" => FontStyle::Oblique,
    53	                    _ => FontStyle::Normal,
    54	                },
    55	                letter_spacing,
    56	                preserve_space,
    57	            };
    58	            match measure_text(&fonts, &text, &font) {
    59	                Ok(metrics) => metrics.to_json().to_string(),
    60	                Err(d) => serde_json::json!({ "error": d.message }).to_string(),
    61	            }
    62	        },
    63	    )
    64	    .map_err(host_error)?;
    65	    let assets = library.clone();
    66	    let names = Function::new(ctx.clone(), move || {
    67	        serde_json::Value::from(assets.asset_names()).to_string()
    68	    })
    69	    .map_err(host_error)?;
    70	    let warn = Function::new(ctx.clone(), move |message: String| {
    71	        sink.borrow_mut().push(message);
    72	    })
    73	    .map_err(host_error)?;
    74	    let colour = Function::new(ctx.clone(), named_colour).map_err(host_error)?;
