751	     2	// Written from scratch after the published simplex construction (skewed
752	     3	// simplex grid, gradient table, radial falloff). Evaluated as a SCRIPT after
753	     4	// `stdlib.js`, so `noise2D` and `noise3D` are globals. Each answers a value
754	     5	// in [-1, 1] that depends only on its arguments.
755	     6	
756	     7	const __noise = (() => {
757	     8	  const GRAD3 = [
758	     9	    [1, 1, 0], [-1, 1, 0], [1, -1, 0], [-1, -1, 0],
759	    10	    [1, 0, 1], [-1, 0, 1], [1, 0, -1], [-1, 0, -1],
760	    11	    [0, 1, 1], [0, -1, 1], [0, 1, -1], [0, -1, -1],
761	    12	  ];
762	    13	  const tables = new Map();
763	    14	
764	    15	  // The seed's permutation of 0–255, doubled to 512 entries: a Fisher–Yates
765	    16	  // shuffle driven by splitmix32 from an FNV-1a hash of `String(seed)` (the
766	    17	  // hash `random` uses). Cached per seed; a cache changes no answer.
767	    18	  function permutation(seed) {
768	    19	    const key = String(seed);
769	    20	    let perm = tables.get(key);
770	    21	    if (perm) return perm;
771	    22	    let h = 0x811c9dc5;
772	    23	    for (let i = 0; i < key.length; i++) {
773	    24	      h ^= key.charCodeAt(i);
774	    25	      h = Math.imul(h, 0x01000193);
775	    26	    }
776	    27	    let state = h | 0;
777	    28	    const next = () => {
778	    29	      state = (state + 0x9e3779b9) | 0;
779	    30	      let t = state ^ (state >>> 16);
780	    31	      t = Math.imul(t, 0x21f0aaad);
781	    32	      t ^= t >>> 15;
782	    33	      t = Math.imul(t, 0x735a2d97);
783	    34	      t ^= t >>> 15;
784	    35	      return t >>> 0;
785	    36	    };
786	    37	    const p = [];
787	    38	    for (let i = 0; i < 256; i++) p.push(i);
788	    39	    for (let i = 255; i > 0; i--) {
789	    40	      const j = next() % (i + 1);
790	    41	      const swap = p[i];
791	    42	      p[i] = p[j];
792	    43	      p[j] = swap;
793	    44	    }
794	    45	    perm = new Uint8Array(512);
795	    46	    for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
796	    47	    if (tables.size >= 64) tables.clear();
797	    48	    tables.set(key, perm);
798	    49	    return perm;
799	    50	  }
