     1	//! The Library: the font set and the asset map a graphic draws with, built
     2	//! from bytes the caller read (G-2, G-6 — never `load_system_fonts`), its
     3	//! content version, the `measure_text` memo, and the usvg options every
     4	//! parse shares, whose resolvers record what resvg itself never reports.
     5	//! The generic families `serif`, `sans-serif` and `monospace` are named on
     6	//! the database (G-6), and a font is chosen from the text's OWN families
     7	//! only, never usvg's appended `serif` fallback. Its `usage()` is every font
     8	//! blob and asset those resolvers handed a parse or a measure (G-46 (b)).
     9	
    10	use std::collections::{BTreeMap, BTreeSet, HashMap};
    11	use std::sync::{Arc, Mutex, MutexGuard};
    12	
    13	use resvg::usvg;
    14	use resvg::usvg::fontdb;
    15	use sha2::{Digest, Sha256};
    16	
    17	use crate::diagnostic::Diagnostic;
    18	use crate::images::{cached_kind, Asset};
    19	use crate::measure::{FontStyle, TextMetrics};
    20	
    21	/// `(family, size bits, weight, style, letter-spacing bits, preserve, text)`.
    22	pub(crate) type MemoKey = (String, u64, u16, FontStyle, u64, bool, String);
    23	
    24	/// The memo is cleared when it reaches this many entries.
    25	const MEMO_CAP: usize = 4096;
    26	
    27	/// The engine's fonts and assets. Immutable once built; `Send + Sync`.
    28	pub struct Library {
    29	    db: Arc<fontdb::Database>,
    30	    assets: BTreeMap<String, Asset>,
    31	    families: Vec<String>,
    32	    version: String,
    33	    warnings: Vec<Diagnostic>,
    34	    memo: Mutex<HashMap<MemoKey, TextMetrics>>,
    35	    /// Each loaded face's blob: its index in `new()`'s `fonts`.
    36	    blobs: HashMap<fontdb::ID, usize>,
    37	    used: Mutex<Used>,
    38	}
    39	
    40	/// What every parse and measure against one library has used, cumulative
    41	/// over its life (G-46 (b)): the font blobs whose faces were selected,
    42	/// directly or as a fallback, as indexes into `Library::new`'s `fonts`
    43	/// (faceless blobs counted), ascending; and the assets resolved as images,
    44	/// by name, sorted.
    45	#[derive(Debug, Clone, Default, PartialEq, Eq)]
    46	pub struct Usage {
    47	    pub fonts: Vec<usize>,
    48	    pub assets: Vec<String>,
    49	}
    50	
    51	#[derive(Default)]
    52	struct Used {
    53	    fonts: BTreeSet<usize>,
    54	    assets: BTreeSet<String>,
    55	}
    56	
    57	/// One loaded face.
    58	#[derive(Debug, Clone, PartialEq, Eq)]
    59	pub struct Face {
    60	    pub family: String,
    61	    pub post_script_name: String,
    62	    pub weight: u16,
    63	    pub italic: bool,
    64	}
    65	
    66	/// What one parse's resolvers saw: the family lists no face answered, the
    67	/// hrefs that name no asset, whether a data: URL was met, and the assets
    68	/// that are not images.
    69	#[derive(Default)]
    70	pub(crate) struct Probe {
    71	    pub(crate) families: Vec<Vec<usvg::FontFamily>>,
    72	    pub(crate) hrefs: Vec<String>,
    73	    pub(crate) data_url: bool,
    74	    pub(crate) bad_assets: Vec<String>,
    75	}
    76	
    77	/// Every closure takes the lock only for its own push: a nested SVG asset
    78	/// re-enters `select_font` on the same thread, and the lock is not
    79	/// re-entrant.
    80	pub(crate) fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    81	    mutex
    82	        .lock()
    83	        .unwrap_or_else(|poisoned| poisoned.into_inner())
    84	}
    85	
    86	impl Library {
    87	    pub fn new(fonts: Vec<Vec<u8>>, assets: BTreeMap<String, Vec<u8>>) -> Library {
    88	        let version = version_of(&fonts, &assets);
    89	        let mut db = fontdb::Database::new();
    90	        let mut warnings = Vec::new();
    91	        let mut blobs = HashMap::new();
    92	        for (index, bytes) in fonts.into_iter().enumerate() {
    93	            let ids = db.load_font_source(fontdb::Source::Binary(Arc::new(bytes)));
    94	            if ids.is_empty() {
    95	                warnings.push(Diagnostic::warning(format!("font {index} loaded no face")));
    96	            }
    97	            for id in ids {
    98	                blobs.insert(id, index);
    99	            }
   100	        }
   101	        // G-6's generics; `cursive` and `fantasy` keep fontdb's defaults,
   102	        // which the set lacks, so they are warned like any missing family.
   103	        db.set_serif_family("Source Serif 4");
   104	        db.set_sans_serif_family("Source Sans 3");
   105	        db.set_monospace_family("IBM Plex Mono");
   106	        let mut families: Vec<String> = db
   107	            .faces()
   108	            .filter_map(|face| face.families.first().map(|(name, _)| name.clone()))
   109	            .collect();
   110	        families.sort();
   111	        families.dedup();
   112	        Library {
   113	            db: Arc::new(db),
   114	            assets: assets
   115	                .into_iter()
   116	                .map(|(name, data)| {
   117	                    let digest = Sha256::digest(&data).into();
   118	                    let data = Arc::new(data);
   119	                    (name, Asset { data, digest })
   120	                })
   121	                .collect(),
   122	            families,
   123	            version,
   124	            warnings,
   125	            memo: Mutex::new(HashMap::new()),
   126	            blobs,
   127	            used: Mutex::new(Used::default()),
   128	        }
   129	    }
   130	
   131	    /// The font blobs and assets every parse and measure against this
   132	    /// library has used so far.
   133	    pub fn usage(&self) -> Usage {
   134	        let used = lock(&self.used);
   135	        Usage {
   136	            fonts: used.fonts.iter().copied().collect(),
   137	            assets: used.assets.iter().cloned().collect(),
   138	        }
   139	    }
   140	
   141	    /// Records a selected face's blob; called after usvg's own work, so no
   142	    /// other lock is held.
   143	    fn record_font(&self, id: fontdb::ID) {
   144	        if let Some(&index) = self.blobs.get(&id) {
   145	            lock(&self.used).fonts.insert(index);
   146	        }
   147	    }
   148	
   149	    /// Primary family names, sorted and deduplicated.
   150	    pub fn families(&self) -> &[String] {
   151	        &self.families
   152	    }
   153	
   154	    pub fn faces(&self) -> Vec<Face> {
   155	        self.db
   156	            .faces()
   157	            .map(|face| Face {
   158	                family: face
   159	                    .families
   160	                    .first()
   161	                    .map(|(name, _)| name.clone())
   162	                    .unwrap_or_default(),
   163	                post_script_name: face.post_script_name.clone(),
   164	                weight: face.weight.0,
   165	                italic: face.style != fontdb::Style::Normal,
   166	            })
   167	            .collect()
   168	    }
   169	
   170	    pub fn asset_names(&self) -> Vec<&str> {
   171	        self.assets.keys().map(String::as_str).collect()
   172	    }
   173	
   174	    pub fn asset(&self, name: &str) -> Option<&[u8]> {
   175	        self.assets.get(name).map(|asset| asset.data.as_slice())
   176	    }
   177	
   178	    /// SHA-256 of the font and asset bytes, 64 lowercase hex characters.
   179	    pub fn version(&self) -> &str {
   180	        &self.version
   181	    }
   182	
   183	    /// One per font blob that loaded no face.
   184	    pub fn warnings(&self) -> &[Diagnostic] {
   185	        &self.warnings
   186	    }
   187	
   188	    pub(crate) fn memo_get(&self, key: &MemoKey) -> Option<TextMetrics> {
   189	        lock(&self.memo).get(key).copied()
   190	    }
   191	
   192	    pub(crate) fn memo_put(&self, key: MemoKey, metrics: TextMetrics) {
   193	        let mut memo = lock(&self.memo);
   194	        if memo.len() >= MEMO_CAP {
   195	            memo.clear();
   196	        }
   197	        memo.insert(key, metrics);
   198	    }
   199	
   200	    /// The options every parse uses: this font set only, `<image>` hrefs
   201	    /// answered from the asset map only, and every miss recorded in
   202	    /// `probe`. Every face selected (directly or as a fallback) and every
   203	    /// asset resolved as an image is recorded in the usage set, each closure
   204	    /// locking it only after usvg's own call returns. `Options` is not
   205	    /// `Clone`, so each call builds its own.
   206	    pub(crate) fn options<'a>(&'a self, probe: &'a Mutex<Probe>) -> usvg::Options<'a> {
   207	        let select_font: usvg::FontSelectionFn<'a> = Box::new(move |font, db| {
   208	            let id = select_font(font, db);
   209	            match id {
   210	                Some(id) => self.record_font(id),
   211	                None => lock(probe).families.push(font.families().to_vec()),
   212	            }
   213	            id
   214	        });
   215	        let fallback = usvg::FontResolver::default_fallback_selector();
   216	        let select_fallback: usvg::FallbackSelectionFn<'a> = Box::new(move |c, used, db| {
   217	            let id = fallback(c, used, db);
   218	            if let Some(id) = id {
   219	                self.record_font(id);
   220	            }
   221	            id
   222	        });
   223	        let resolve_data: usvg::ImageHrefDataResolverFn<'a> = Box::new(move |_, _, _| {
   224	            lock(probe).data_url = true;
   225	            None
   226	        });
   227	        let resolve_string: usvg::ImageHrefStringResolverFn<'a> =
   228	            Box::new(move |href, opts| match self.assets.get(href) {
   229	                Some(asset) => {
   230	                    let kind = image_kind(asset, opts);
   231	                    if kind.is_none() {
   232	                        lock(probe).bad_assets.push(href.to_string());
   233	                    } else {
   234	                        lock(&self.used).assets.insert(href.to_string());
   235	                    }
   236	                    kind
   237	                }
   238	                None => {
   239	                    lock(probe).hrefs.push(href.to_string());
   240	                    None
   241	                }
   242	            });
   243	        usvg::Options {
   244	            fontdb: self.db.clone(),
   245	            font_resolver: usvg::FontResolver {
   246	                select_font,
   247	                select_fallback,
   248	            },
   249	            image_href_resolver: usvg::ImageHrefResolver {
   250	                resolve_data,
   251	                resolve_string,
   252	            },
   253	            ..usvg::Options::default()
   254	        }
   255	    }
