260	/// Removes this thread's entries whose module has been dropped everywhere,
261	/// and answers them so the caller drops them outside the map's borrow.
262	fn sweep(map: &mut HashMap<u64, Entry>) -> Vec<Entry> {
263	    let dead: Vec<u64> = map
264	        .iter()
265	        .filter(|(_, (weak, _, _))| weak.strong_count() == 0)
266	        .map(|(id, _)| *id)
267	        .collect();
268	    dead.into_iter().filter_map(|id| map.remove(&id)).collect()
269	}
