271	/// Removes the least recently used entries while the map holds more than
272	/// `ENGINES_PER_THREAD`, and answers them so the caller drops them outside
273	/// the map's borrow. The entry adopted last holds the highest stamp, so it
274	/// is never one of them.
275	fn evict(map: &mut HashMap<u64, Entry>) -> Vec<Entry> {
276	    let mut evicted = Vec::new();
277	    while map.len() > ENGINES_PER_THREAD {
278	        let oldest = map
279	            .iter()
280	            .min_by_key(|(_, (_, stamp, _))| *stamp)
281	            .map(|(id, _)| *id);
282	        match oldest.and_then(|id| map.remove(&id)) {
283	            Some(entry) => evicted.push(entry),
284	            None => break,
285	        }
286	    }
287	    evicted
288	}
