290	/// Keeps `engine` as this thread's engine for the module `inner`, stamped
291	/// as the most recently used, and evicts past `ENGINES_PER_THREAD`.
292	pub(crate) fn adopt(inner: &Arc<Inner>, engine: Engine) {
293	    let (dead, evicted) = ENGINES.with(|engines| {
294	        let mut engines = engines.borrow_mut();
295	        let dead = sweep(&mut engines.map);
296	        engines.uses += 1;
297	        let stamp = engines.uses;
298	        engines
299	            .map
300	            .insert(inner.id, (Arc::downgrade(inner), stamp, engine));
301	        let evicted = evict(&mut engines.map);
302	        (dead, evicted)
303	    });
304	    drop(dead);
305	    drop(evicted);
306	}
