308	/// Runs `f` on this thread's engine for `module`, building it by `load`
309	/// when this thread has none. The map is not borrowed while `f` runs.
310	fn with_engine<T>(
311	    module: &Module,
312	    budget_ms: u64,
313	    f: impl FnOnce(&mut Engine) -> Result<T, Diagnostic>,
314	) -> Result<T, Diagnostic> {
315	    let inner = module.inner();
316	    let (dead, found) = ENGINES.with(|engines| {
317	        let mut engines = engines.borrow_mut();
318	        let dead = sweep(&mut engines.map);
319	        let found = engines.map.remove(&inner.id);
320	        (dead, found)
321	    });
322	    drop(dead);
323	    let mut engine = match found {
324	        Some((_, _, engine)) => engine,
325	        None => {
326	            let mut engine = Engine::new(module.library())?;
327	            engine.load(module.name(), module.source(), budget_ms)?;
328	            engine
329	        }
330	    };
331	    let answer = f(&mut engine);
332	    adopt(inner, engine);
333	    answer
334	}
