 11	/// The pending exception of `e` as a Diagnostic; line and column from
 12	/// `stack`, preferring a frame in the module `name`.
 13	pub(crate) fn diagnose(
 14	    ctx: &rquickjs::Ctx<'_>,
 15	    e: rquickjs::Error,
 16	    name: &str,
 17	    frame: Option<i64>,
 18	) -> Diagnostic {
 19	    let mut d = Diagnostic::error(e.to_string());
 20	    d.frame = frame;
 21	    if !matches!(e, rquickjs::Error::Exception) {
 22	        return d;
 23	    }
 24	    let caught = ctx.catch();
 25	    let mut stack = None;
 26	    if let Some(exception) = caught.as_exception() {
 27	        let kind: Option<String> = exception.get("name").ok();
 28	        let message = exception.message().unwrap_or_default();
 29	        d.message = match kind {
 30	            Some(kind) if !kind.is_empty() => format!("{kind}: {message}"),
 31	            _ => message,
 32	        };
 33	        stack = exception.stack();
 34	    } else if let Some(text) = caught.as_string().and_then(|s| s.to_string().ok()) {
 35	        d.message = text;
 36	    } else {
 37	        d.message = format!("threw {}", caught.type_name());
 38	    }
 39	    if let Some((line, column)) = stack.as_deref().and_then(|s| position(s, name)) {
 40	        d.line = Some(line);
 41	        d.column = Some(column);
 42	    }
 43	    d
 44	}
 45	
 46	/// The `L:C` of the first stack frame whose file ends with `name`, else of
 47	/// the first frame (quickjs-ng writes `    at render (<name>:L:C)`; the
 48	/// standard library and the sandbox are `eval_script`).
 49	pub(crate) fn position(stack: &str, name: &str) -> Option<(u32, u32)> {
 50	    let mut first = None;
 51	    for line in stack.lines() {
 52	        let trimmed = line.trim().trim_end_matches(')');
 53	        let mut parts = trimmed.rsplitn(3, ':');
 54	        let (Some(col), Some(row), Some(rest)) = (parts.next(), parts.next(), parts.next()) else {
 55	            continue;
 56	        };
 57	        let (Ok(col), Ok(row)) = (col.parse::<u32>(), row.parse::<u32>()) else {
 58	            continue;
 59	        };
 60	        if rest.ends_with(name) {
 61	            return Some((row, col));
 62	        }
 63	        first.get_or_insert((row, col));
 64	    }
 65	    first
 66	}
