 68	/// `d` in the budget's words when the call's deadline had passed. An
 69	/// interrupt's position is the function's, and the sentence says so.
 70	pub(crate) fn budgeted(mut d: Diagnostic, expired: bool, budget_ms: u64) -> Diagnostic {
 71	    if !expired {
 72	        return d;
 73	    }
 74	    d.message = match (d.frame, d.line, d.column) {
 75	        (None, _, _) => format!("over the {budget_ms} ms budget while loading ({})", d.message),
 76	        (Some(f), Some(l), Some(c)) => format!(
 77	            "over the {budget_ms} ms budget at frame {f} ({}); {l}:{c} is where the function begins, not the statement that ran long",
 78	            d.message
 79	        ),
 80	        (Some(f), _, _) => format!("over the {budget_ms} ms budget at frame {f} ({})", d.message),
 81	    };
 82	    d
 83	}
