 87	pub(crate) fn returned_svg(value: Value<'_>, frame: i64) -> Result<String, Diagnostic> {
 88	    let message = if let Some(text) = value.as_string() {
 89	        match text.to_string() {
 90	            Ok(text) if text.len() > SVG_BYTES => format!(
 91	                "render returned {} bytes at frame {frame}; the SVG may be at most {SVG_BYTES} bytes",
 92	                text.len()
 93	            ),
 94	            Ok(text) if text.starts_with("<svg") => return Ok(text),
 95	            Ok(text) => {
 96	                let head: String = text.chars().take(40).collect();
 97	                format!(
 98	                    "render returned a string that does not start with <svg at frame {frame}: {head:?}"
 99	                )
100	            }
101	            Err(_) => format!(
102	                "render's string could not be read at frame {frame} — is it tens of megabytes?"
103	            ),
104	        }
105	    } else if value.is_undefined() {
106	        format!("render returned undefined at frame {frame} — did you forget `return`?")
107	    } else {
108	        // rquickjs names numbers `int` and `float`; an author knows `number`.
109	        let kind = match value.type_name() {
110	            "int" | "float" => "number",
111	            "bool" => "boolean",
112	            other => other,
113	        };
114	        format!("render returned {kind} at frame {frame}; it must return an SVG string")
115	    };
116	    let mut d = Diagnostic::error(message);
117	    d.frame = Some(frame);
118	    Err(d)
119	}
