// How far 64 uniform chords fall short of a cubic's true length, over random
// and hard curves; the same flattening path.js uses (__PATH_CHORDS = 64).
const at = (p, t) => {
  const u = 1 - t;
  return [
    u*u*u*p[0] + 3*u*u*t*p[2] + 3*u*t*t*p[4] + t*t*t*p[6],
    u*u*u*p[1] + 3*u*u*t*p[3] + 3*u*t*t*p[5] + t*t*t*p[7],
  ];
};
const len = (p, n) => {
  let [px, py] = at(p, 0), L = 0;
  for (let i = 1; i <= n; i++) {
    const [x, y] = at(p, i / n);
    L += Math.hypot(x - px, y - py);
    px = x; py = y;
  }
  return L;
};
let worst = 0, worstP = null, errs = [];
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
for (let k = 0; k < 20000; k++) {
  const p = [];
  for (let i = 0; i < 8; i++) p.push(Math.round(rnd() * 1000));
  const a = len(p, 64), b = len(p, 8192);
  const e = (100 * (b - a)) / b;
  errs.push(e);
  if (e > worst) { worst = e; worstP = p; }
}
errs.sort((a, b) => a - b);
console.log("median %", errs[errs.length >> 1], "p99 %", errs[Math.floor(errs.length * 0.99)], "max %", worst, worstP);
for (const p of [
  [0, 0, 1000, 0, -900, 0, 100, 0],
  [0, 0, 1000, 1, -900, 1, 100, 0],
  [0, 0, 100, 100, 0, 100, 100, 0],
]) {
  const a = len(p, 64), b = len(p, 262144);
  console.log(p.join(" "), (100 * (b - a)) / b);
}

